// Fim dos Tempos · Arco 2 · Aventura 1 · gerado por a2-av1-stremtol.js
const PISTAS = [["geral",["dipl","enga","furt","inve","nobr","perc","intu"],15,"Os moradores estão inquietos com a presença dos heróis, mas são receptivos à Guarda."],["geral",["dipl","enga","furt","inve","nobr","perc"],15,"Os primeiros moradores foram Remont e Ysmenne Ronchetillon."],["geral",["dipl","enga","furt","inve","nobr","perc"],15,"A vizinhança é nova: a primeira casa foi construída há menos de 5 anos."],["geral",["dipl","enga","furt","inve","nobr","perc"],15,"Todos os moradores são famílias e casais relativamente jovens."],["geral",["dipl","enga","furt","inve","nobr"],20,"A área é tecnicamente dos Ronchetillon, cedida a cada morador para construir a casa. Em termos legais, os moradores são vassalos deles."],["geral",["dipl","enga","furt","inve","nobr"],20,"A família Elbannise (de Osmont) tem laços antigos de amizade com os Ronchetillon."],["geral",["dipl","enga","furt","inve","nobr"],20,"Só algumas famílias são aceitas em Stremtol. O critério é misterioso; não basta \"ser nobre\"."],["geral",["dipl","enga","furt","inve","nobr"],20,"Periodicamente há reuniões da vizinhança na casa dos Ronchetillon. Parece uma comunidade unida, embora pequena."],["geral",["dipl","enga","inve","nobr"],25,"Há uma clara intenção de tornar Stremtol diferente das regiões nobres: arquitetura, roupas e jeito de falar lembram uma aldeia. Não há servos."],["geral",["dipl","enga","inve","nobr"],25,"A vizinhança não exclui não humanos."],["geral",["dipl","enga","inve","nobr"],25,"Nenhum morador mantém laços próximos com a família fora da vizinhança."],["geral",["dipl","enga","inve","nobr","guer"],25,"Não há nenhum tipo de guarda ou exército particular em Stremtol."],["geral",["dipl","enga","inve","nobr","reli"],25,"Todas as famílias cultuam Khalmyr, mas não há nenhum clérigo na vizinhança."],["geral",["dipl","enga","inve","nobr","mist","reli"],25,"Não há iluminação mágica, runas de proteção, bênçãos nem defesas arcanas ou divinas na vizinhança."],["geral",["dipl","enga","inve"],30,"As reuniões acontecem toda semana, mas às vezes há mais de uma por semana (não se sabe em que casos)."],["geral",["dipl","enga","inve"],30,"Nunca houve apresentações de bardos. Alguns moradores já apresentaram uma peça ou cantaram para os outros."],["geral",["dipl","enga","inve","reli"],30,"Embora Khalmyr seja um deus guerreiro, os moradores não acreditam em vingança nem em justiça violenta: preferem perdoar, quase como devotos de Thyatis."],["geral",["mist"],35,"Não há nada mágico acontecendo aqui, mas nada bloqueia a magia."],["geral",["sobr"],35,"Nenhum monstro passou por aqui nos últimos meses ou anos."],["geral",["intu"],35,"Todos aqui são felizes e parecem se amar muito."],["geral",["ofic"],35,"As casas foram construídas com técnicas humanas, sem apoio mágico ou divino, nem trabalho de monstros ou golens."],["geral",["intu"],40,"Há uma divisão: cada casa parece ter um morador de um \"lado\" e outro do \"outro lado\". Não são rivais; é só identificação com um grupo."],["aldanna",[],0,"Na parede está a cabeça empalhada do javali Aníbal, o antigo companheiro animal de Aldanna (reconhecível pela pintura no quarto de Torzogh)."],["aldanna",["reli"],15,"Há um pequeno altar a Khalmyr, simples e humilde, feito para a própria família conduzir os rituais, como em aldeias sem clérigo."],["aldanna",["inve"],20,"Exceto pela cabeça do javali, não há nenhum resquício da antiga vida de Aldanna: nenhuma arma, armadura ou lembrança."],["aldanna",["inve"],25,"Há objetos de interesse de Osmont (negócios, heráldica, um retrato dele jovem), mas nada de Aldanna além de roupas e utensílios domésticos."],["aldanna",[],0,"Aldanna é absolutamente sincera em tudo (qualquer teste de Intuição). Não esconde nada nem parece forçada."],["aldanna",[],0,"Ela fez parte dos Mata-Malvados por anos, mas vê isso como \"uma brincadeira juvenil\". Prefere se concentrar no futuro."],["aldanna",[],0,"Teve um relacionamento com Torzogh e terminaram amigavelmente. Tem carinho por ele e gostaria que ele largasse a vida de aventureiro para \"crescer\"."],["aldanna",[],0,"De início resistiu a Osmont e, casada, ainda \"teimou\" na vida de aventureira. Tem vergonha disso e é grata a ele por tê-la \"ajudado a crescer\"."],["aldanna",["intu"],20,"Ela vê aventureiros com condescendência; respeita um pouco o grupo por ser da Guarda, mas acha a postura deles um pouco ridícula."],["aldanna",["intu"],25,"Fica desconfortável ao falar de habilidades especiais, magia e poderes, e mais ainda ao vê-los em ação: medo e vergonha."],["aldanna",["guer","intu"],30,"De alguma forma, Aldanna perdeu ou esqueceu suas habilidades. Não sabe mais nem disparar um arco."],["aldanna",["int"],20,"Há uma lacuna de alguns meses entre as brigas com Osmont e a mudança para Stremtol que ela não menciona."],["aldanna",["intu"],25,"Ela não esconde o período \"vazio\": é como se não existisse. Questionada, sorri e diz que \"ficou se preparando\". Não lembra detalhes; acha que foi o nervosismo."],["aldanna",["intu"],25,"Aldanna é genuinamente feliz."],["aldanna",["intu"],30,"Aldanna está sempre feliz, como se fosse incapaz de sentir tristeza, raiva, medo ou qualquer emoção forte."],["inagar",["inve"],20,"Há um alçapão coberto por um tapete na sala. Leva a um porão com vários baús cheios de grimórios."],["inagar",["mist"],20,"Os grimórios são bastante avançados."],["inagar",["inve","perc"],15,"Não há nenhum livro na casa além dos grimórios escondidos."],["inagar",[],0,"Inagar tem muita vergonha do passado de mago, um gatilho para Albert. Quando perguntam da vida anterior, desconversa."],["inagar",[],0,"Inagar não tem medo de Albert, mas não quer ferir os sentimentos dele, então escolhe bem as palavras (ou seja, o tempo todo)."],["inagar",["intu"],25,"Inagar não fala do passado para não magoar Albert."],["inagar",["perc"],20,"Os dois não fazem nada separados."],["inagar",["intu"],20,"Inagar é muito mais inteligente do que deixa transparecer, muito acima de um aprendiz de mais de 30 anos."],["inagar",["intu"],25,"Inagar tem vergonha de ser só um aprendiz na Guilda dos Contadores."],["inagar",["intu"],20,"Os dois realmente se amam, mas Albert é muito inseguro."],["inagar",["intu"],25,"Inagar é feliz, mas a felicidade não condiz com a vida dele: comportamento de infeliz, sentimento de feliz."],["illydna",["inve","perc"],15,"Há muitas roupas luxuosas para Alvuriell, mas Illydna tem só três vestidos simples de serva."],["illydna",[],0,"A casa não é feita para alguém da estatura de um goblin: Alvuriell mal alcança as prateleiras."],["illydna",["conh","inve","perc"],20,"Há pergaminhos de canções e poesias élficas e até uma lira élfica. Alvuriell não tem nada em termos de diversão ou interesses."],["illydna",["intu"],20,"A elfa sente, acima de tudo, pena do goblin."],["illydna",[],0,"Os dois sempre dizem que Illydna \"salvou\" Alvuriell."],["illydna",[],0,"O goblin fala sem vergonha do passado de ladrão, frisando como estava errado e como Illydna lhe deu tudo."],["illydna",["dipl","enga"],30,"O nome original de Alvuriell era Grug."],["illydna",["nobr","perc"],20,"Alvuriell tem maneirismos de quem aprendeu etiqueta numa escola, não em casa."],["remont",[],0,"Uma porta dentro da casa está sempre fechada (tranca comum, de boa qualidade)."],["remont",["ladi"],20,"Atrás da porta fechada há um pequeno escritório com os cinco <b>Dossiês do Aluno</b> (handout no diário)."],["remont",[],0,"Embora seja a casa de um alto nobre, não há ornamentos nem flâmulas com o brasão dos Ronchetillon."],["remont",[],0,"Há uma sala com cinco cadeiras em semicírculo, mesinhas e uma prateleira de bebidas. Parece uma sala de reuniões."],["remont",["dipl","enga","intu"],25,"Ysmenne não sabe o que há atrás da porta, só que é \"assunto de Remont\"."],["remont",["dipl","enga","perc"],25,"As reuniões da vizinhança acontecem na sala das cinco cadeiras."],["remont",["dipl","enga","perc"],30,"Os participantes das reuniões são só Remont, Osmont, Albert, Illydna e Hugo."],["remont",["dipl","enga","intu"],30,"Ysmenne sai de casa quando há reunião, para deixar os convidados à vontade. Em geral visita Aldanna ou Rosa."],["remont",["dipl","enga","intu"],30,"Ysmenne não sabe o que é discutido nas reuniões, nem por que ela e os outros não são convidados."],["remont",["intu"],30,"Nunca ocorreu a Ysmenne perguntar o que é discutido ou por que ela não pode ouvir."],["remont",["nobr"],25,"Ysmenne tem maneirismos de etiqueta aprendidos numa escola depois de adulta, não naturais."],["remont",["nobr"],25,"Os maneirismos de Ysmenne são os mesmos de Aldanna, Inagar, Alvuriell e Rosa."],["hugo",[],0,"Nenhum dos dois parece saber cuidar da casa ou da plantação."],["hugo",["ofic"],20,"Embora humilde, a casa usa os mesmos materiais caros das outras."],["hugo",["ofic"],25,"A casa é mais que humilde: é antiquada, quase falsa, como se alguém imitasse uma casa pobre."],["hugo",["nobr","ofic"],20,"Hugo e Rosa vestem roupas de camponeses, mas limpas e bem costuradas demais. Parecem fantasias."],["hugo",["conh"],15,"Os dois usam um vocabulário atípico para gente tão simples."],["hugo",["nobr"],15,"Os dois têm maneirismos de etiqueta que lembram nobres."],["hugo",["nobr"],25,"Rosa tem os mesmos maneirismos dos outros: parece ter aprendido numa escola."],["hugo",["nobr"],20,"Hugo parece ter nascido nobre."],["hugo",["nobr"],30,"Hugo é um alto nobre de Valkaria (o conde Labonnet)."],["hugo",["mist"],25,"A pele de Rosa tem marcas de uso de magia e ela tem uma espécie de aura mágica."],["hugo",["mist"],30,"As marcas e a aura de Rosa são típicas de necromancia."],["hugo",["conh","inve","mist"],35,"Rosa é a notória necromante <b>Rozaryth Dez Caveiras</b>, capturada por aventureiros há cerca de dois anos."],["hugo",["intu"],25,"Rosa realmente não lembra do passado. Perguntar o que fazia antes de Hugo soa absurdo para ela."]];
const CASAS = {"geral":"Stremtol (informações gerais)","aldanna":"Osmont e Aldanna Elbannise","inagar":"Inagar e Albert","illydna":"Illydna e Alvuriell","remont":"Remont e Ysmenne Ronchetillon","hugo":"Hugo, Rosa e Luka"};
const NOMES_PERICIA = {"dipl":"Diplomacia","enga":"Enganação","furt":"Furtividade","inve":"Investigação","nobr":"Nobreza","perc":"Percepção","intu":"Intuição","guer":"Guerra","reli":"Religião","mist":"Misticismo","sobr":"Sobrevivência","ofic":"Ofício","conh":"Conhecimento","ladi":"Ladinagem","int":"Inteligência"};
(async function macroInvestigar() {
		const atores = canvas.tokens.controlled.map((t) => t.actor).filter(Boolean);
		const opCasas = Object.entries(CASAS).map(([k, n]) => `<option value="${k}">${n}</option>`).join("");
		const opPer = Object.entries(NOMES_PERICIA).map(([k, n]) => `<option value="${k}">${n}</option>`).join("");
		const res = await foundry.applications.api.DialogV2.prompt({
			window: { title: "Investigar Stremtol" },
			content: `
				<div class="form-group"><label>Onde</label><select name="casa">${opCasas}</select></div>
				<div class="form-group"><label>Perícia</label><select name="per">${opPer}</select></div>
				<div class="form-group"><label>Resultado já rolado (opcional)</label><input type="number" name="manual" placeholder="rolar para os tokens selecionados"></div>
				<div class="form-group"><label>Incluir as pistas sem teste</label><input type="checkbox" name="semTeste"></div>`,
			ok: { label: "Investigar", callback: (ev, button) => Object.fromEntries(new FormData(button.form)) }
		});
		if (!res) return;
		const bonus = (a, k) => {
			if (k === "int") return Number(a.system.atributos?.int?.value) || 0;
			if (k === "ofic") return Math.max(0, ...Object.entries(a.system.pericias ?? {}).filter(([kk]) => kk.startsWith("ofi")).map(([, v]) => Number(v?.value) || 0));
			return Number(a.system.pericias?.[k]?.value) || 0;
		};
		const rolls = [];
		let melhor = Number(res.manual);
		let html = `<h3>${CASAS[res.casa]} · ${NOMES_PERICIA[res.per]}</h3>`;
		if (!res.manual) {
			if (!atores.length) return ui.notifications.warn("Selecione os tokens de quem investiga, ou informe o resultado.");
			melhor = -99;
			html += "<ul>";
			for (const a of atores) {
				const r = await new Roll(`1d20 + ${bonus(a, res.per)}`).evaluate();
				rolls.push(r);
				melhor = Math.max(melhor, r.total);
				html += `<li>${a.name}: <b>${r.total}</b></li>`;
			}
			html += "</ul>";
		}
		const daCasa = PISTAS.filter((x) => x[0] === res.casa);
		const reveladas = daCasa.filter(([, per, cd]) => cd && per.includes(res.per) && cd <= melhor).sort((a, b) => a[2] - b[2]);
		const proximas = daCasa.filter(([, per, cd]) => cd && per.includes(res.per) && cd > melhor);
		html += `<p>Melhor resultado: <b>${melhor}</b>. Cada teste revela uma informação; bons testes podem revelar mais (você escolhe).</p>`;
		html += reveladas.length ? `<ul>${reveladas.map(([, , cd, t]) => `<li>(CD ${cd}) ${t}</li>`).join("")}</ul>` : "<p><i>Nada com esta perícia.</i></p>";
		if (proximas.length) html += `<p style="font-size:0.85em">Ainda escondido com esta perícia: ${proximas.length} pista(s), CD ${proximas.map((x) => x[2]).join(", ")}.</p>`;
		if (res.semTeste) {
			const livres = daCasa.filter((x) => !x[2]);
			if (livres.length) html += `<p><b>Sem teste:</b></p><ul>${livres.map((x) => `<li>${x[3]}</li>`).join("")}</ul>`;
		}
		ChatMessage.create({ content: html, rolls, whisper: ChatMessage.getWhisperRecipients("GM") });
	})();
